import {families,family,rgb,hsv,oklab,swatchRecords,traditionalId,materialLabel,nearestTraditional} from './colour-model.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=hex=>hex.toUpperCase();
let material='全部',hue='',search='',page=0,sort='object';const size=40;
try{
 const [artifacts,literature,traditional]=await Promise.all(['data/artifacts.json?v=20261004','data/colour-literature.json','data/traditional-colours.json'].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error('色彩资料暂时未能读取');return r.json()}));
 const names=new Map(literature.names.map(n=>[n.id,n])),records=swatchRecords(artifacts).map(r=>({...r,match:nearestTraditional(r.hex,traditional.colors)})),familyMap=new Map(families.map(f=>[f.id,f]));
 const name=r=>r.match.name;
 $('swatch-count').textContent=records.length;$('object-count').textContent=artifacts.length;$('core-copy').textContent=literature.core.body;
 $('core-citation').innerHTML=`依据 ${esc(literature.core.source)}，${esc(literature.core.pages)}整理。<br>另参：<a href="${literature.core.museumUrl}" target="_blank" rel="noopener">${literature.core.museumTitle} ↗</a>`;
 const examples=['red','black','yellow','green','ochre','white'].map(f=>{const candidates=records.filter(r=>r.family===f&&r.weight>=.08);const choices=f==='red'?candidates.filter(r=>r.artifact.materialGroup==='漆器'):f==='black'?candidates.filter(r=>r.artifact.id==='drum'):f==='green'?candidates.filter(r=>r.artifact.materialGroup==='青铜'):f==='white'?candidates.filter(r=>r.artifact.materialGroup==='陶瓷'):f==='ochre'?candidates.filter(r=>r.artifact.materialGroup==='玉石'):f==='yellow'?candidates.filter(r=>hsv(r.hex).v>.70&&hsv(r.hex).h<64):candidates;return (choices.length?choices:candidates).sort((a,b)=>b.weight-a.weight)[0]}).filter(Boolean);
 $('core-strips').innerHTML=examples.map(r=>`<button class="core-strip" data-swatch="${r.id}" style="--swatch:${r.hex};--strip-text:${oklab(r.hex)[0]>.64?'#373c2f':'#eee4cc'}"><span class="core-strip-name">${familyMap.get(r.family).name}</span><img src="${esc(r.artifact.displayImage||r.artifact.image)}" alt="${esc(r.artifact.title)}"><small>${esc(r.artifact.short||r.artifact.title)}<b>${fmt(r.hex)}</b></small></button>`).join('');
 const materials=['全部',...new Set(artifacts.map(materialLabel).filter(m=>m&&!/待|未/.test(m)))];
 $('material-nav').innerHTML=materials.map(m=>`<button data-material="${esc(m)}" aria-pressed="${m===material}">${esc(m==='全部'?'全部器物':m+'色谱')}<small>${artifacts.filter(a=>m==='全部'||materialLabel(a)===m).length}</small></button>`).join('');
 $('family-nav').innerHTML='<button data-family="" aria-pressed="true">全部</button>'+families.map(f=>`<button data-family="${f.id}" style="--dot:${f.hex}" aria-pressed="false"><i></i>${f.name}</button>`).join('');
 $('naming-method').textContent='每一枚照片颜色都在《中国传统颜色在线手册》的 '+traditional.colors.length+' 条色卡中，以 OKLab 感知色差寻找最近的具体色名。点击色卡可并列查看照片原值与色谱参考值。色名和参考 HEX 原样取自该现代色谱，不自行命名；下方古籍释色另列来源，不把现代色号当成古代标准。';
 $('literature-list').innerHTML=literature.names.map(n=>`<details><summary>${n.name}<small>古籍色词</small></summary><blockquote>“${esc(n.quote)}”</blockquote><a href="${n.url}" target="_blank" rel="noopener">${esc(n.work)} ↗</a><p>${esc(n.meaning)}</p></details>`).join('');
 $('standards-note').innerHTML=`本页匹配色谱：<a href="${traditional.source.dataURL}" target="_blank" rel="noopener">${traditional.source.name} ↗</a> · ${traditional.colors.length} 色 · ${traditional.source.author} · <a href="data/traditional-colours-LICENSE.txt">MIT 许可</a><br>另参现代标准：<a href="${literature.standards.url}" target="_blank" rel="noopener">${esc(literature.standards.name)} ↗</a><br>${esc(literature.standards.note)}`;
 let visible=[];
 function render(){visible=records.filter(r=>(material==='全部'||materialLabel(r.artifact)===material)&&(!hue||r.family===hue)&&(!search||[r.hex,r.artifact.title,r.artifact.material,r.artifact.city,name(r),names.get(r.traditional)?.work].some(s=>s?.toLowerCase().includes(search))));
  if(sort==='hue')visible.sort((a,b)=>hsv(a.hex).h-hsv(b.hex).h);else if(sort==='light')visible.sort((a,b)=>oklab(b.hex)[0]-oklab(a.hex)[0]);
  page=Math.min(page,Math.max(0,Math.ceil(visible.length/size)-1));$('result-count').textContent=`${new Set(visible.map(r=>r.artifact.id)).size} 件器物 · ${visible.length} 个色样`;$('catalogue-title').textContent=material==='全部'?'器物色谱':material+'色谱';
  $('swatch-grid').innerHTML=visible.slice(page*size,(page+1)*size).map(r=>`<button class="swatch-card" data-swatch="${r.id}" aria-label="${esc(r.artifact.title)} ${fmt(r.hex)} ${name(r)}，查看色卡"><span class="swatch-circle" style="--swatch:${r.hex}"></span><strong>${name(r)}</strong><span class="swatch-kind">近似传统色</span><code>${fmt(r.hex)}</code><span class="rgb">RGB ${rgb(r.hex).join(' / ')}</span><span class="swatch-source">${esc(r.artifact.title)}</span><span class="swatch-ratio">原取色占比 ${r.share}%</span></button>`).join('')||'<p class="empty-colours">没有找到这一组颜色。换个词或清除筛选试试。</p>';
  $('page-count').textContent=`${page+1} / ${Math.max(1,Math.ceil(visible.length/size))}`;$('previous-page').disabled=page===0;$('next-page').disabled=(page+1)*size>=visible.length;
  document.querySelectorAll('[data-material]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===material)));document.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.family===hue)));
 }
 function detail(id){const r=records.find(x=>x.id===id);if(!r)return;const n=names.get(r.traditional),a=r.artifact;
  $('colour-detail-content').innerHTML=`<div class="detail-colour-top"><div class="detail-pigment" style="--swatch:${r.hex};--strip-text:${oklab(r.hex)[0]>.64?'#373c2f':'#eee4cc'}"><strong>${name(r)}</strong><code>${fmt(r.hex)}</code><small>RGB ${rgb(r.hex).join(' / ')}</small></div><div class="detail-object"><img src="${esc(a.displayImage||a.image)}" alt="${esc(a.title)}"><h3>${esc(a.title)}</h3><p>${esc(a.material)} · 原取色占比 ${r.share}%</p><a href="object.html?id=${a.id}">进入器物档案 ↗</a></div></div><div class="detail-colour-copy"><span class="folio">传统色谱 / 最近色匹配</span><h3>色谱中的“${esc(r.match.name)}”</h3><div class="reference-colour-pair"><span><i style="background:${r.hex}"></i>照片取色 <code>${fmt(r.hex)}</code></span><span><i style="background:${r.match.hex}"></i>色谱参考 <code>${fmt(r.match.hex)}</code></span></div><p>近似对应 <a href="${traditional.source.dataURL}" target="_blank" rel="noopener">${traditional.source.name} ↗</a> 中的“${esc(r.match.name)}”（条目 ${r.match.id}）。${r.match.distance<.045?'两者色感较接近。':'两者仍有偏差，保留照片原色，不用参考色覆盖它。'}</p>${n?`<h4>同色域的古籍用字 · ${n.name}</h4><blockquote>“${esc(n.quote)}”</blockquote><a href="${n.url}" target="_blank" rel="noopener">${esc(n.work)} ↗</a><p>${esc(n.meaning)}</p>`:'<p>该色谱名的古籍出处尚未逐条证实，暂不附会古籍引文。</p>'}<p class="small">${esc(a.paletteMethod||'从器物照片前景取色。')}。受光照、保存状况及拍摄条件影响，不代表原始颜料测色。照片 HEX 与现代色谱参考 HEX 分列；古籍引文只解释相关色词，不为现代色号背书。</p><div class="detail-colour-actions"><button id="copy-hex">复制 ${fmt(r.hex)}</button><a href="colour-lab.html?object=${a.id}&hex=${r.hex.slice(1)}">加入我的配色 ↗</a></div></div>`;
  $('copy-hex').onclick=async e=>{try{await navigator.clipboard.writeText(fmt(r.hex));e.target.textContent='已复制 '+fmt(r.hex)}catch{e.target.textContent=fmt(r.hex)+' · 请手动复制'}};$('colour-detail').showModal();
 }
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.swatch)detail(b.dataset.swatch);if(b.dataset.material){material=b.dataset.material;page=0;render()}if(b.hasAttribute('data-family')){hue=b.dataset.family;page=0;render()}});
 $('colour-search').oninput=e=>{search=e.target.value.trim().toLowerCase();page=0;render()};$('colour-sort').onchange=e=>{sort=e.target.value;page=0;render()};$('clear-colours').onclick=()=>{material='全部';hue='';search='';$('colour-search').value='';page=0;render()};
 const move=d=>{page+=d;render();$('catalogue-title').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})};$('previous-page').onclick=()=>move(-1);$('next-page').onclick=()=>move(1);document.querySelector('.colour-close').onclick=()=>$('colour-detail').close();$('colour-detail').addEventListener('click',e=>{if(e.target===$('colour-detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
 render();document.body.dataset.ready='true';
}catch(e){document.querySelector('.colour-paper').innerHTML='<p role="alert">'+esc(e.message)+'。请刷新重试。</p>';console.error(e)}
